package com.gameaggregator.ledgerservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="adjustments") public class Adjustment{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String idempotencyKey;@Column(nullable=false)public UUID originalTransactionId;@Column(nullable=false,precision=19,scale=6)public BigDecimal amountDelta;@Column(nullable=false)public String reason;@Column(nullable=false)public UUID createdBy;@Column(nullable=false)public Instant createdAt=Instant.now();protected Adjustment(){}public Adjustment(String i,UUID t,BigDecimal a,String r,UUID u){idempotencyKey=i;originalTransactionId=t;amountDelta=a;reason=r;createdBy=u;}}